/// A template block: its position in the template, its state, its payload.
#[derive(Clone, Copy, Debug)]
pub struct Block {
    /// Position in the template, before rotation.
    pub pos: [i16; 3],
    /// Index into [`STATES`].
    pub state: u16,
    /// A `PAYLOAD_*` value: the block entity the template carries.
    pub payload: u8,
}

/// A jigsaw connector a template carries.
#[derive(Clone, Copy, Debug)]
pub struct Jigsaw {
    /// Position in the template, before rotation.
    pub pos: [i16; 3],
    /// Index into [`STATES`]: the jigsaw block's own state, whose `orientation`
    /// names its front and top.
    pub state: u16,
    /// The pool this connector draws from.
    pub pool: &'static str,
    /// This connector's name, which a child's `target` must equal.
    pub name: &'static str,
    /// The name this connector wants on the child it attaches to.
    pub target: &'static str,
    /// The state the connector block becomes once placed.
    pub final_state: u16,
}

/// One carried template.
#[derive(Clone, Copy, Debug)]
pub struct Template {
    /// The id a pool entry names, `betterdungeons:small_dungeon/shells/small_shell_5x5`.
    pub id: &'static str,
    /// Its size, before rotation.
    pub size: [i16; 3],
    /// Its blocks, in the template's own order.
    pub blocks: &'static [Block],
    /// Its jigsaw connectors.
    pub jigsaws: &'static [Jigsaw],
}

